"""Predict a GeoTIFF tile using a checkpoint generated by train.py."""
import argparse
from pathlib import Path
import numpy as np
import rasterio
import torch
from datasets.tree_dataset import read_image, preprocess, digest
from training.common import load_checkpoint, device_from, seed_all, write_json


def main():
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument('--input', type=Path, required=True)
    p.add_argument('--checkpoint', type=Path, required=True)
    p.add_argument('--output', type=Path, required=True)
    p.add_argument('--bands', nargs=4, type=int, metavar=('R','G','B','NIR'), help='Explicit stored order for this input; defaults to the checkpoint order')
    p.add_argument('--device', choices=['cpu','cuda'], default='cpu')
    a = p.parse_args()
    if a.output.resolve() in [a.input.resolve(),a.checkpoint.resolve()]:
        p.error('Output must not overwrite input or checkpoint.')
    if a.output.suffix.lower() not in ['.tif','.tiff']:
        p.error('Output must have a .tif or .tiff extension.')
    device = device_from(a.device)
    model, saved = load_checkpoint(a.checkpoint, device)
    cfg = saved['config']
    seed_all(cfg['seed'],cfg['threads'])
    bands = a.bands if a.bands is not None else cfg['bands']
    raw, profile = read_image(a.input, bands)
    with torch.inference_mode():
        probability = model(preprocess(raw)[None].to(device))[0,0].cpu().numpy()
    mask = (probability > cfg['threshold']).astype(np.uint8)*255
    a.output.parent.mkdir(parents=True,exist_ok=True)
    with rasterio.open(a.output,'w',driver='GTiff',height=mask.shape[0],width=mask.shape[1],count=1,dtype='uint8',
                       crs=profile['crs'],transform=profile['transform'],compress='deflate') as dst:
        dst.write(mask,1)
    write_json(a.output.with_suffix('.json'),{'input':a.input.name,'input_sha256':digest(a.input),'checkpoint_sha256':digest(a.checkpoint),
                                             'bands':bands,'threshold':cfg['threshold'],'comparison':'strictly greater','mask_values':[0,255]})
    print(a.output)


if __name__ == '__main__': main()
